 async function openPaths(paths:string[],pw=''){opening=true;for(const path of paths){try{const existing=docs.find(d=>d.path===path);if(existing){activeId=existing.id;section='reader';continue;}const d=await api.open(path,pw);docs=[...docs,d];activeId=d.id;editor=null;hits=[];searchIndex=-1;mode='read';page=Number(readSetting('bpdf-page:'+d.path,'0'));page=Math.min(Math.max(page,0),d.pages-1);section='reader';remember(d);passwordPath='';password='';await tick();if(page)go(page);}catch(e){if(String(e).includes('PASSWORD_REQUIRED')){passwordPath=path;passwordError=pw?t('密码不正确，请重试。','Incorrect password. Try again.'):'';password='';}else notify(String(e));}}opening=false;}
 async function choosePDF(){if(!native){notify(t('这是界面预览。请启动 BPDF 桌面应用以处理文件。','This is a UI preview. Start the BPDF desktop app to work with files.'));return;}try{const files=await open({multiple:true,filters:[{name:'PDF / Office',extensions:['pdf','doc','docx','xls','xlsx','ppt','pptx']}]});if(files)await openPaths(Array.isArray(files)?files:[files]);}catch(e){notify(String(e));}}
 async function closeDoc(id:string){if(editing){notify(t('请等待当前修改完成。','Wait for the current edit to finish.'));return;}if(rooms[id]&&!await confirm(t('关闭此标签将结束或退出协作。请先另存需要保留的修改，仍要关闭吗？','Closing this tab ends or leaves the collaboration. Save changes you want to keep first. Close?'),{title:'BPDF',kind:'warning'}))return;const d=docs.find(x=>x.id===id);if((d?.dirty||officePending(officeDrafts[id]))&&!await confirm(t('这个文档有未另存的修改，仍要关闭吗？','This document has unsaved changes. Close it?'),{title:'BPDF',kind:'warning'}))return;await api.close(id);docs=docs.filter(d=>d.id!==id);delete rooms[id];delete officeDrafts[id];if(activeId===id){activeId=docs.at(-1)?.id||'';if(!activeId)section='home';}}
