 let showQuit=$state(false),quitBusy=$state(false),quitError=$state('');
 async function finishQuit(choice:'save'|'copy'|'discard'){
  if(quitBusy)return;quitBusy=true;quitError='';
  try{
   if(editing||roomSyncs.size||(running&&choice!=='discard'))throw Error(t('请等待当前编辑、转换或同步完成；也可以先在任务页取消转换。','Wait for editing, conversion or sync to finish, or cancel conversions in Tasks.'));
