     if(officePending(draft)){d=await invoke<DocumentSession>('edit_office',{id:d.id,item:draft.item.id,text:draft.text,kind:draft.kind,style:$state.snapshot(draft.style),revision:draft.revision});docs=docs.map(x=>x.id===d.id?d:x);delete officeDrafts[d.id];}
