      const output=await save({defaultPath:d.name.replace(/\.[^.]+$/,'')+'-edited.'+(d.format||'pdf'),filters:[{name:(d.format||'pdf').toUpperCase(),extensions:[d.format||'pdf']}]});
      if(!output)return;await api.save(d.id,output);
     }else await invoke('save_original_document',{id:d.id});
