 async function saveCopy(){if(!active||editing)return;if(officePending(officeDrafts[active.id])){notify(t('请先应用当前修改，再另存。','Apply the current change before saving.'));return;}const d=active;try{const out=await save({defaultPath:d.name.replace(/\.[^.]+$/,'')+'-edited.'+(d.format||'pdf'),filters:[{name:(d.format||'pdf').toUpperCase(),extensions:[d.format||'pdf']}]});if(out){await api.save(d.id,out);docs=docs.map(x=>x.id===d.id?{...x,dirty:false}:x);notify(t('已另存，原文件未修改。','Saved a copy. The original is unchanged.'));}}catch(e){notify(String(e));}}
 async function history(direction:string){if(!active||rooms[active.id]||editing)return;if(officePending(officeDrafts[active.id])){notify(t('请先应用或取消当前修改。','Apply or discard the current change first.'));return;}delete officeDrafts[active.id];try{const d=await api.history(active.id,direction);docs=docs.map(x=>x.id===d.id?d:x);editor=null;}catch(e){notify(String(e));}}
