 function flattenOutline(items:any[],depth=0):{title:string;page:number;depth:number}[]{return items.flatMap(x=>[{title:x.title,page:typeof x.page==='number'?x.page:typeof x.page?.page==='number'?x.page.page:0,depth},...flattenOutline(x.down||x.children||[],depth+1)]);}
 async function print(){if(!active)return;try{await api.print(active.id);notify(t('已打开系统 PDF 预览，请在预览中选择打印。','Opened the system PDF preview. Choose Print there.'));}catch(e){notify(String(e));}}
