 async function previewEdit(){if(!active||!editor||previewing)return;const signature=previewSignature;previewing=true;try{const image=await api.previewEdit(active.id,$state.snapshot(editor),active.revision);if(signature===previewSignature)editPreview=image;}catch(e){if(signature===previewSignature)notify(String(e));}finally{previewing=false;}}
 function key(e:KeyboardEvent){
  if(showQuit){if(e.key==='Escape'&&!quitBusy){showQuit=false;e.preventDefault();}return;}if(e.defaultPrevented)return;if(e.key===' '&&e.target instanceof HTMLElement&&e.target.closest('button'))return;
  const el=e.target instanceof HTMLElement?e.target:null;const input=!!el&&(el.matches('input,textarea,select')||el.isContentEditable);
  if(e.key==='Escape'){if(showShortcuts){showShortcuts=false;return;}if(showSettings){showSettings=false;return;}if(selectedTool){selectedTool=null;return;}if(showCollaboration){showCollaboration=false;return;}if(editor){editor=null;return;}if(fullscreen){void toggleFullscreen();return;}mode='read';return;}
  if(showShortcuts||showSettings||selectedTool||showCollaboration||passwordPath)return;
  if(native&&isMac&&e.metaKey&&!['+','tab'].includes(e.key.toLowerCase())&&!(e.ctrlKey&&e.key.toLowerCase()==='f'))return;
  const action=shortcut(e,input);if(action){e.preventDefault();menuAction(action);}
