 async function leaveRoom(){if(!active)return;await invoke('collaboration_leave',{id:active.id});delete rooms[active.id];showCollaboration=false;}
 async function syncRooms(force=false){if(editing||showQuit)return;await Promise.all(Object.keys(rooms).map(async id=>{if(roomSyncs.has(id)||(!force&&(rooms[id].nextRetry||0)>Date.now()))return;roomSyncs.add(id);rooms[id]={...rooms[id],syncing:true};try{const d=await syncQueue.run(()=>invoke<DocumentSession>('collaboration_sync',{id}));if(!rooms[id])return;docs=docs.map(old=>old.id===id&&old.revision<d.revision?d:old);rooms[id]={...rooms[id],error:undefined,failures:0,nextRetry:0,lastSync:Date.now()};}catch(e){if(rooms[id]){const failures=(rooms[id].failures||0)+1;rooms[id]={...rooms[id],error:String(e),failures,nextRetry:Date.now()+Math.min(30000,2000*2**Math.min(failures,4))};}}finally{roomSyncs.delete(id);if(rooms[id])rooms[id]={...rooms[id],syncing:false};}}));}
