 async function menuAction(action:string){
  if(showQuit)return;
  if(action==='shortcuts'){showShortcuts=true;return;}
  if(showShortcuts||showSettings||selectedTool||showCollaboration||passwordPath)return;
  if(action==='fullscreen'){await toggleFullscreen();return;}
  if(action==='next-pane'||action==='previous-pane'){const panes=[...document.querySelectorAll<HTMLElement>('.document-sidebar .side-tabs button:first-child,.page-viewport,.edit-inspector textarea,.reader-toolbar .toolbar-group:first-child button:first-child')].filter(e=>e.offsetParent!==null);const i=panes.indexOf(document.activeElement as HTMLElement);panes[(i+(action==='next-pane'?1:-1)+panes.length)%panes.length]?.focus();return;}
  if(action==='next-tab'||action==='previous-tab'){if(docs.length){const i=docs.findIndex(d=>d.id===activeId);switchDoc(docs[(i+(action==='next-tab'?1:-1)+docs.length)%docs.length].id);}return;}

  if(action==='settings'){showSettings=true;return;}if(action==='open'){await choosePDF();return;}
  if(action==='tools'){section='tools';await tick();document.querySelector<HTMLInputElement>('.tool-search input')?.focus();return;}
  if(action==='tasks'){section='tasks';return;}if(action==='share'){showCollaboration=true;return;}if(action==='github'){await openGithub();return;}
  if(action==='undo'||action==='redo'){const el=document.activeElement;if(el instanceof HTMLElement&&(el.matches('input,textarea')||el.isContentEditable)){document.execCommand(action);return;}await history(action);return;}
  if(!active)return;
  const focused=document.activeElement;if(focused instanceof HTMLElement&&(focused.matches('input,textarea,select')||focused.isContentEditable)&&['first','last','previous','next'].includes(action))return;
  if(action==='close-tab'){await closeDoc(active.id);return;}if(action==='save'){await saveCopy();return;}if(action==='print'){await print();return;}
  section='reader';await tick();
  if(action==='find'&&active.format&&active.format!=='pdf'){document.querySelector<HTMLInputElement>('.office-search input')?.focus();return;}
  if(action==='find'){sidebar=true;sideTab='search';await tick();document.querySelector<HTMLInputElement>('.doc-search input')?.focus();}
  if(action==='zoom-in')zoom(.1);if(action==='zoom-out')zoom(-.1);if(action==='fit')fit();if(action==='sidebar')sidebar=!sidebar;
  if(action==='previous')go(page-1);if(action==='next')go(page+1);
  if(action==='first')go(0);if(action==='last')go(active.pages-1);
  if(action==='go-page'){const field=document.querySelector<HTMLInputElement>('.page-number');field?.focus();field?.select();}
  if(action==='actual-size')scale=1;
  if(action==='fit-page'&&viewport){const b=active.bounds[page];scale=Math.max(.1,Math.min(2.5,(viewport.clientWidth-48)/((b[2]-b[0])*(view==='spread'?2:1)),(viewport.clientHeight-48)/(b[3]-b[1])));}
  if(action==='screen-up'||action==='screen-down'){const delta=action==='screen-up'?-1:1;if(view==='single')go(page+delta);else viewport?.scrollBy({top:delta*viewport.clientHeight*.9,behavior:'instant'});}
  if(action==='next-result'||action==='previous-result'){if(hits.length){searchIndex=(searchIndex+(action==='next-result'?1:-1)+hits.length)%hits.length;go(hits[searchIndex].page);}else{sidebar=true;sideTab='search';}}
  if(action.startsWith('view-'))view=action.slice(5);
  if(action.startsWith('mode-')){if(active.format&&active.format!=='pdf'){notify(t('Office 内容请使用右侧兼容编辑面板。','Use the Office editor on the right.'));return;}mode=action.slice(5);editTools=true;editor=null;}

 }
 $effect(()=>{if(native&&isMac)invoke('update_native_menu',{language:lang,hasDocument:!!active}).catch(e=>notify(String(e)));});
 onMount(()=>{if(!native||!isMac)return;let ended=false;let stop:(()=>void)|undefined;listen<string>('menu-action',e=>{menuAction(e.payload).catch(e=>notify(String(e)));}).then(fn=>{if(ended)fn();else stop=fn;});return()=>{ended=true;stop?.();};});
 onMount(()=>{const timer=setInterval(()=>syncRooms(),2000);return()=>clearInterval(timer);});
 onMount(()=>{try{recent=JSON.parse(readSetting('bpdf-recent','[]'));}catch{}if(!native)return;const cleanups:(()=>void)[]=[];let ended=false;(async()=>{try{caps=await api.capabilities();taskList=await api.tasks();const a=await listen<Task>('task-updated',e=>{taskList=[...taskList.filter(t=>t.id!==e.payload.id),e.payload].slice(-200);});const b=await listen<string[]>('open-files',e=>openPaths(e.payload));const c=await getCurrentWebviewWindow().onDragDropEvent(e=>{dropActive=e.payload.type==='enter'||e.payload.type==='over';if(e.payload.type==='drop'){dropActive=false;openPaths(e.payload.paths.filter(p=>/\.(pdf|docx?|xlsx?|pptx?)$/i.test(p)));}});const close=await getCurrentWebviewWindow().onCloseRequested(async event=>{flushPosition();if(editor||docs.some(d=>d.dirty)||Object.values(officeDrafts).some(officePending)||editing||running||Object.keys(rooms).length){event.preventDefault();showQuit=true;quitError='';}});cleanups.push(a,b,c,close);if(ended)cleanups.forEach(c=>c());const launch=await invoke<string[]>('launch_files');if(launch.length)openPaths(launch);}catch(e){notify(String(e));}})();return()=>{ended=true;cleanups.forEach(c=>c());};});
