<svelte:window onkeydown={key} onresize={()=>resizedWidth(paneWidth)}/>
<div class="app-shell" class:mac={isMac} class:reading={section==='reader'} class:fullscreen>
 {#if section!=='reader'}<div class="window-drag-handle" data-tauri-drag-region aria-hidden="true"></div>{/if}

 <div class="workspace">
  {#if fullscreen}<div class="fullscreen-edge" aria-hidden="true"></div>{/if}
  <nav class="rail" aria-label={t('主导航','Main navigation')}><button class:active={section==='home'} class="rail-button" title={t('主页','Home')} onclick={()=>section='home'}><BookOpen size={21}/><span>{t('主页','Home')}</span></button><button class:active={section==='tools'} class="rail-button" title={t('全部工具','All tools')} onclick={()=>section='tools'}><Grid2X2 size={21}/><span>{t('工具','Tools')}</span></button><button class:active={section==='tasks'} class="rail-button" title={t('任务','Tasks')} onclick={()=>section='tasks'}><div class="badge-wrap"><Clock3 size={21}/>{#if running}<b>{running}</b>{/if}</div><span>{t('任务','Tasks')}</span></button>{#if docs.length||fullscreen}<div class="rail-separator"></div><button disabled={!docs.length} class:active={section==='reader'} class="rail-button" title={t('阅读','Read')} onclick={()=>section='reader'}><FileText size={21}/><span>{t('阅读','Read')}</span></button>{/if}<button class="rail-button" title={t('局域网协作','LAN collaboration')} onclick={()=>showCollaboration=true}><Users size={20}/><span>{t('协作','Share')}</span></button><div class="rail-bottom"><button class="rail-button" title={t('设置','Settings')} onclick={()=>showSettings=true}><Settings2 size={20}/><span>{t('设置','Settings')}</span></button></div></nav>
  <main use:motion={{key:section,kind:'page'}}>
   {#if section==='home'}
    <div class="home-page"><div class="home-heading"><h1>Better PDF</h1><p>Make PDF better</p></div>
     <button class="open-zone" onclick={choosePDF}><div class="paper-art"><div class="paper-back"></div><div class="paper-front"><span class="paper-corner"></span><span class="paper-label">PDF</span><i></i><i></i><i></i></div><span class="paper-plus"><Plus size={21}/></span></div><div class="open-copy"><strong>{t('打开文档','Open a document')}</strong><span>{t('PDF、Word、Excel、PowerPoint','PDF, Word, Excel, PowerPoint')}</span><small>{t('默认本地处理，协作由你开启','Local by default. Share only when you choose.')}</small></div><span class="open-button"><FolderOpen size={17}/>{t('选择文件','Choose a file')}<kbd>⌘ O</kbd></span></button>
     <div class="section-heading"><h2>{t('常用工具','Everyday essentials')}</h2><button class="text-button" onclick={()=>section='tools'}>{t('查看全部 34 个工具','Explore all 34 tools')}<ArrowRight size={15}/></button></div>
     <div class="quick-grid">{#each popular as id}{@const tool=toolById(id)}{@const Icon=toolIcon(id)}<button class="quick-card" use:motion={{kind:'item'}} onclick={()=>launchTool(tool)}><span class="tool-icon {toolColor(id)}"><Icon size={21}/></span><strong>{tool[lang==='zh'?'zh':'en']}</strong><span>{tool[lang==='zh'?'desc':'descEn']}</span><ArrowUpRight size={15} class="card-arrow"/></button>{/each}</div>
     <div class="section-heading recent-heading"><h2>{t('最近打开','Recently opened')}</h2>{#if recent.length}<button class="text-button subdued" onclick={()=>{recent=[];localStorage.removeItem('bpdf-recent');}}>{t('清空记录','Clear history')}</button>{/if}</div>
     {#if recent.length}<div class="recent-list">{#each recent as file}<button onclick={()=>openPaths([file.path])}><span class="recent-file-icon"><FileText size={19}/></span><span class="recent-name"><strong>{file.name}</strong><small>{file.path}</small></span><time>{new Date(file.date).toLocaleDateString(lang==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric'})}</time><ChevronRight size={16}/></button>{/each}</div>{:else}<div class="recent-empty" use:motion={{kind:'feedback'}}><Clock3 size={18}/><span>{t('打开过的文档会出现在这里','Your recently opened documents will appear here')}</span></div>{/if}
     <footer class="home-footer"><button class="text-button" onclick={openGithub}><Github size={15}/> GitHub</button><small>BPDF · 0.1.0</small></footer>
    </div>
   {:else if section==='tools'}
    <div class="tools-page"><div class="page-heading"><div><span class="eyebrow">A TOOL FOR EVERY PAGE</span><h1>{t('所有工具','All tools')}</h1><p>{t('小而专注的工具，处理文档的每一种需要。','Purposeful tools for every part of your document workflow.')}</p></div><label class="tool-search"><Search size={17}/><input bind:value={query} placeholder={t('搜索工具…','Search tools…')}/><kbd>⌘ K</kbd></label></div><div class="filter-chips"><button class:chosen={category==='all'} onclick={()=>category='all'}>{t('全部','All')} <small>34</small></button>{#each groups as g}<button class:chosen={category===g.id} onclick={()=>category=g.id}>{g[lang==='zh'?'zh':'en']}</button>{/each}</div>
     {#each groups as group}{@const items=filteredTools.filter(t=>t.group===group.id)}{#if items.length}<section class="tool-group"><h2><span class="group-dot {group.color}"></span>{group[lang==='zh'?'zh':'en']}<small>{items.length}</small></h2><div class="tools-grid">{#each items as tool (tool.id)}{@const Icon=toolIcon(tool.id)}<button class="tool-card" use:motion={{kind:'item'}} onclick={()=>launchTool(tool)}><span class="tool-icon {group.color}"><Icon size={20}/></span><div><strong>{tool[lang==='zh'?'zh':'en']}</strong><p>{tool[lang==='zh'?'desc':'descEn']}</p></div><ChevronRight size={15}/></button>{/each}</div></section>{/if}{/each}{#if !filteredTools.length}<div class="empty-state" use:motion={{kind:'feedback'}}><Search size={35}/><h2>{t('没有找到匹配的工具','No matching tools')}</h2><button class="text-button" onclick={()=>{query='';category='all';}}>{t('清除筛选','Clear filters')}</button></div>{/if}
    </div>
   {:else if section==='tasks'}
    <div class="tasks-page"><div class="page-heading"><div><span class="eyebrow">WORKING QUIETLY, LOCALLY</span><h1>{t('处理任务','Your tasks')}</h1><p>{t('转换在后台进行，你可以继续阅读。','Conversions run in the background while you keep reading.')}</p></div></div>{#if !taskList.length}<div class="empty-state" use:motion={{kind:'feedback'}}><Clock3 size={40} strokeWidth={1.2}/><h2>{t('这里还很安静','Nothing in the queue')}</h2><p>{t('从工具中开始一个任务，进度和结果会出现在这里。','Start with a tool. Progress and results will appear here.')}</p><button class="primary" onclick={()=>section='tools'}>{t('浏览工具','Explore tools')}<ArrowRight size={16}/></button></div>{/if}
    <div class="task-list">{#each [...taskList].reverse() as task (task.id)}<article class="task-card" use:motion={{key:task.state,kind:'feedback'}}><div class="task-state" class:success={task.state==='completed'} class:failure={task.state==='failed'}>{#if task.state==='completed'}<CheckCircle2 size={24}/>{:else if task.state==='failed'}<XCircle size={24}/>{:else if task.state==='cancelled'}<X size={24}/>{:else}<LoaderCircle size={24} class="spin"/>{/if}</div><div class="task-body"><div class="task-heading"><strong>{toolById(task.tool)?.[lang==='zh'?'zh':'en']||task.tool}</strong><span>{t(({completed:'已完成',failed:'失败',cancelled:'已取消',running:'处理中',queued:'等待中'}as Record<string,string>)[task.state],task.state)}</span></div>{#if task.state==='running'||task.state==='queued'}<div class="progress-track"><div style:width="{Math.max(2,task.progress*100)}%"></div></div>{/if}<p class:task-error={task.state==='failed'}>{task.message}</p>{#each task.warnings as warning}<p class="task-warning">{warning}</p>{/each}{#each task.outputs as path}<button class="text-button output-link" onclick={()=>revealItemInDir(path)}><FolderOpen size={15}/>{path.split(/[\\/]/).pop()}<ArrowUpRight size={14}/></button>{/each}</div>{#if task.state==='running'||task.state==='queued'}<button class="secondary" onclick={()=>api.cancel(task.id)}>{t('取消','Cancel')}</button>{/if}</article>{/each}</div></div>
