    <div class="reader-shell"><div class="document-tabs" data-tauri-drag-region>{#each docs as doc}<div class:current={doc.id===activeId} class="document-tab"><button onclick={()=>switchDoc(doc.id)}><FileText size={15}/><span>{doc.name}</span>{#if doc.dirty}<b class="dirty-dot"></b>{/if}</button><button title={t('关闭文档','Close document')} onclick={()=>closeDoc(doc.id)}><X size={13}/></button></div>{/each}<button class="icon-button" title={t('打开文档','Open document')} onclick={choosePDF}><Plus size={17}/></button></div>
     <div class="reader-content">
      {#if sidebar}<aside class="document-sidebar" style:width="{paneWidth}px" style:min-width="{paneWidth}px" in:surfaceTransition={{kind:'panel'}} out:surfaceTransition={{kind:'panel',exit:true}}><div class="side-tabs"><button class:chosen={sideTab==='pages'} title={t('页面','Pages')} onclick={()=>sideTab='pages'}><Layers size={17}/></button><button class:chosen={sideTab==='outline'} title={t('目录','Outline')} onclick={()=>sideTab='outline'}><List size={17}/></button><button class:chosen={sideTab==='search'} title={t('搜索','Search')} onclick={()=>sideTab='search'}><Search size={17}/></button></div><div class="side-scroll" use:motion={{key:sideTab,kind:'panel'}}>{#if sideTab==='pages'}{#key active.id}<ThumbnailPages doc={active} width={paneWidth-42} {page} onselect={go}/>{/key}{:else if sideTab==='outline'}{#each flattenOutline(active.outline) as item}<button class="outline-item" style:padding-left="{14+item.depth*12}px" onclick={()=>go(item.page)}>{item.title}</button>{:else}<p class="side-empty">{t('文档没有目录','No document outline')}</p>{/each}{:else}<form class="doc-search" onsubmit={e=>{e.preventDefault();doSearch();}}><input bind:value={searchQuery} placeholder={t('查找文字…','Find text…')}/><button class="icon-button" type="submit" disabled={searching}><Search size={16}/></button></form>{#if searching}<div class="side-empty"><span class="spinner"></span></div>{/if}{#each hits as hit}<button class="search-result" onclick={()=>go(hit.page)}><strong>{t('第','Page')} {hit.page+1} {t('页','')}</strong><span>{searchQuery}</span></button>{/each}{/if}</div><!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions --><div role="separator" tabindex="0" aria-label={t('调整分页栏宽度','Resize page pane')} aria-orientation="vertical" aria-valuemin="150" aria-valuemax="420" aria-valuenow={Math.round(paneWidth)} class="pane-resizer" onpointerdown={resizePane} onkeydown={e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();resizedWidth(paneWidth+(e.key==='ArrowRight'?10:-10));}}}></div></aside>{/if}
      <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
      <div class="page-viewport" tabindex="0" role="region" aria-label={t('文档工作区','Document workspace')} use:pinchZoom={zoomAt} bind:this={viewport} use:motion={{key:active.id+':'+view+':'+fullscreen,kind:'document'}}>{#key active.id}<ReaderPages bind:this={pageView} doc={active} {scale} mode={active.format&&active.format!=='pdf'?'read':mode} {view} {page} {viewport} onselect={selection} onvisible={visible} onerror={notify}/>{/key}</div>
      {#if active.format&&active.format!=='pdf'}{#key active.id}<OfficeEditor doc={active} {lang} drafts={officeDrafts} onchange={d=>{docs=docs.map(old=>old.id===d.id?d:old);page=Math.min(page,d.pages-1);}} onbusy={v=>editing=v} onerror={notify}/>{/key}{/if}
      {#if editor&&(!active.format||active.format==='pdf')}<aside class="edit-inspector" in:surfaceTransition={{kind:'panel'}} out:surfaceTransition={{kind:'panel',exit:true}}><div class="field-heading"><strong>{t(editor.kind==='text'?'编辑文字':editor.kind==='image'?'编辑图片':'添加批注',editor.kind==='text'?'Edit text':editor.kind==='image'?'Edit image':'Add note')}</strong><button class="icon-button" onclick={()=>editor=null}><X size={16}/></button></div>{#if rooms[active.id]&&editor.baseRevision!==active.revision}<p class="hint">{t('共享文档有新修改。同页内容可能需要重新选择；其他页修改不影响提交。','The shared document has changed. Reselect if this page changed; other pages do not block your edit.')}</p><button class="secondary" onclick={keepDraft}>{t('保留草稿并重新选择','Keep draft and reselect')}</button>{/if}{#if editor.kind!=='image'&&drafts[active.id]!==undefined}<button class="text-button" onclick={()=>{if(editor)editor.text=drafts[active.id];delete drafts[active.id];}}>{t('恢复保留的文字草稿','Restore saved text draft')}</button>{/if}{#if editor.kind!=='image'}<label>{t('内容','Content')}<textarea rows="6" bind:value={editor.text}></textarea></label>{/if}{#if editor.kind==='text'}<label>{t('字体','Font')}<select bind:value={editor.font}>{#if editor.sourceFont}<option value="__original__">{t('同步原字体','Match original')} · {editor.sourceFont}</option>{/if}<option value="zh-Hans">{t('内置中文字体','Bundled Chinese font')}</option><option value="Helvetica">Helvetica</option><option value="Times-Roman">Times Roman</option><option value="Courier">Courier</option></select></label><label>{t('字号','Font size')}<input type="number" min="4" max="200" bind:value={editor.size}/></label><label>{t('颜色','Color')}<input type="color" value={'#'+(editor.color||[0,0,0]).map((c:number)=>Math.round(c*255).toString(16).padStart(2,'0')).join('')} onchange={e=>{const c=e.currentTarget.value;editor={...editor,color:[parseInt(c.slice(1,3),16)/255,parseInt(c.slice(3,5),16)/255,parseInt(c.slice(5,7),16)/255]};}}/></label><p class="hint">{t('默认同步原字体、字号与颜色。原字体缺字时会提示选择替代字体。','Matches the original font, size and color. Missing glyphs require choosing a replacement font.')}</p>{/if}{#if editor.kind==='image'}<button class="secondary" onclick={replaceImage}><Image size={16}/>{t('选择替换图片','Choose replacement')}</button>{#if editor.path}<p class="hint">{editor.path.split(/[\\/]/).pop()}</p>{/if}{/if}{#if editor.targetRect}<div class="option-grid">{#each ['X','Y',t('右边界','Right'),t('下边界','Bottom')] as label,i}<label>{label}<input type="number" step="1" bind:value={editor.targetRect[i]}/></label>{/each}</div>{/if}<button class="secondary" disabled={editing||previewing} onclick={previewEdit}>{previewing?t('正在生成预览…','Generating preview…'):t('预览修改','Preview changes')}</button>{#if editPreview}<figure class="edit-preview" use:motion={{key:editPreview,kind:'item'}}><img src={editPreview} alt={t('修改后页面预览','Edited page preview')}/><figcaption>{t('预览不更改文档，确认后应用修改。','Preview only. Apply to update the document.')}</figcaption></figure>{/if}<button class="primary" disabled={editing} onclick={()=>editor&&apply($state.snapshot(editor))}>{#if editing}<LoaderCircle size={15} class="spin"/>{:else}<Check size={15}/>{/if}{t('应用修改','Apply changes')}</button>{#if editor.kind==='image'}<button class="text-button danger" disabled={editing} onclick={()=>editor&&apply({...$state.snapshot(editor),remove:true})}>{t('删除这张图片','Delete this image')}</button>{/if}</aside>{/if}
     </div>     <div class="reader-toolbar"><div class="toolbar-group"><button class:pressed={sidebar} class="icon-button" aria-pressed={sidebar} title={t('显示／隐藏分页栏 (F4)','Show / hide page pane (F4)')} onclick={()=>sidebar=!sidebar}><PanelLeft size={18}/></button><button class="icon-button" title={t('上一页','Previous page')} disabled={page===0} onclick={()=>go(page-1)}><ChevronLeft size={18}/></button><input class="page-number" aria-label={t('页码','Page number')} type="number" min="1" max={active.pages} value={page+1} onchange={e=>go(Number(e.currentTarget.value)-1)}/><span class="page-count">/ {active.pages}</span><button class="icon-button" title={t('下一页','Next page')} disabled={page===active.pages-1} onclick={()=>go(page+1)}><ChevronRight size={18}/></button></div><div class="toolbar-group zoom-group"><button class="icon-button" title={t('缩小','Zoom out')} onclick={()=>zoom(-.1)}><ZoomOut size={17}/></button><button class="zoom-label" title={t('适合宽度','Fit width')} onclick={fit}>{Math.round(scale*100)}%</button><button class="icon-button" title={t('放大','Zoom in')} onclick={()=>zoom(.1)}><ZoomIn size={17}/></button><select class="view-select" aria-label={t('阅读模式','View mode')} bind:value={view}><option value="continuous">{t('连续','Continuous')}</option><option value="single">{t('单页','Single page')}</option><option value="spread">{t('双页','Two pages')}</option></select></div><div class="toolbar-group toolbar-right"><button class="icon-button" aria-pressed={fullscreen} disabled={fullscreenBusy} title={t(fullscreen?'退出全屏 (Esc)':'全屏 (⌘/Ctrl L)',fullscreen?'Exit full screen (Esc)':'Full screen (⌘/Ctrl L)')} onclick={toggleFullscreen}>{#if fullscreen}<Minimize2 size={18}/>{:else}<Maximize size={18}/>{/if}</button>{#if rooms[active.id]}<button class="text-button" title={rooms[active.id].error||t('协作已连接','Connected')} onclick={()=>showCollaboration=true}><Users size={15}/>{rooms[active.id].error?t('连接中断','Offline'):t('协作中','Shared')}</button>{/if}{#if !active.format||active.format==='pdf'}<button class="text-button" class:pressed={editTools} onclick={()=>{editTools=!editTools;if(!editTools){mode='read';editor=null;}}}><PenLine size={16}/>{t('编辑','Edit')}</button>{/if}<button class="icon-button" title={t('撤销','Undo')} disabled={!active.canUndo||editing||!!rooms[active.id]} onclick={()=>history('undo')}><Undo2 size={17}/></button><button class="icon-button" title={t('重做','Redo')} disabled={!active.canRedo||editing||!!rooms[active.id]} onclick={()=>history('redo')}><Redo2 size={17}/></button><span class="toolbar-divider"></span><button class="icon-button" title={t('系统打印预览','System print preview')} onclick={print}><Printer size={17}/></button><button class="primary small" onclick={saveCopy}><Download size={15}/>{t('另存为','Save a copy')}</button></div></div>
     {#if editTools&&(!active.format||active.format==='pdf')}<div class="edit-toolbar" in:surfaceTransition={{kind:'item'}} out:surfaceTransition={{kind:'item',exit:true}}><div class="mode-buttons">{#each [{id:'read',zh:'阅读',en:'Read',icon:MousePointer2},{id:'text',zh:'编辑文字',en:'Text',icon:Type},{id:'image',zh:'图片',en:'Images',icon:Image},{id:'highlight',zh:'高亮',en:'Highlight',icon:Highlighter},{id:'note',zh:'批注',en:'Notes',icon:MessageSquare},{id:'ink',zh:'手绘',en:'Draw',icon:PenLine},{id:'form',zh:'表单',en:'Forms',icon:SquareCheck}] as item}{@const Icon=item.icon}<button class:chosen={mode===item.id} onclick={()=>{mode=item.id;editor=null;}}><Icon size={15}/>{item[lang==='zh'?'zh':'en']}</button>{/each}</div><button class="text-button" onclick={()=>section='tools'}><Grid2X2 size={15}/>{t('全部工具','All tools')}</button></div>{/if}
<footer class="reader-status"><span>{active.name}</span><span>{mode==='text'?t('点击文字编辑；双击空白处添加文字','Click text to edit; double-click blank space to add text'):mode==='image'?t('点击图片进行替换或删除','Click an image to replace or delete'):mode==='highlight'?t('拖动选择需要高亮的文字','Drag to select text to highlight'):mode==='ink'?t('在页面上拖动绘制','Drag on the page to draw'):t('原文件未修改','Original file unchanged')}</span><span>{active.pages} {t('页','pages')}</span></footer>
