{#if dropActive}<div class="drop-overlay" in:surfaceTransition={{kind:'backdrop'}} out:surfaceTransition={{kind:'backdrop',exit:true}}><FileText size={48}/><h2>{t('放开，开始阅读','Drop to start reading')}</h2></div>{/if}
{#if passwordPath}<div class="modal-backdrop" use:motion={{kind:'backdrop'}}><form class="compact-dialog" in:surfaceTransition={{kind:'dialog'}} out:surfaceTransition={{kind:'dialog',exit:true}} onsubmit={e=>{e.preventDefault();openPaths([passwordPath],password);}}><h2>{t('打开受保护的文档','Open a protected document')}</h2><p>{passwordPath.split(/[\\/]/).pop()}</p><label>{t('打开密码','Opening password')}<input type="password" bind:value={password} autocomplete="off"/></label>{#if passwordError}<p class="error-message">{passwordError}</p>{/if}<div class="button-row"><button type="button" class="secondary" onclick={()=>passwordPath=''}>{t('取消','Cancel')}</button><button class="primary" type="submit">{t('打开','Open')}</button></div></form></div>{/if}
{#if showSettings}<div class="modal-backdrop" use:motion={{kind:'backdrop'}}><div class="compact-dialog settings-dialog" in:surfaceTransition={{kind:'dialog'}} out:surfaceTransition={{kind:'dialog',exit:true}} role="dialog" aria-modal="true" aria-label={t('设置','Settings')}><div class="field-heading"><h2>{t('偏好设置','Preferences')}</h2><button class="icon-button" onclick={()=>showSettings=false}><X size={18}/></button></div><label>{t('外观','Appearance')}<div class="theme-options">{#each [{id:'light',icon:Sun,zh:'浅色',en:'Light'},{id:'dark',icon:Moon,zh:'深色',en:'Dark'},{id:'system',icon:Monitor,zh:'系统',en:'System'}]as item}{@const Icon=item.icon}<button class:chosen={theme===item.id} onclick={()=>theme=item.id}><Icon size={21}/>{item[lang==='zh'?'zh':'en']}</button>{/each}</div></label><label>{t('界面语言','Interface language')}<select bind:value={lang}><option value="zh">简体中文</option><option value="en">English</option></select></label><div class="settings-note"><ShieldCheck size={20}/><p>{t('文档在本地处理。仅开启协作时，与持有邀请码的局域网成员共享当前副本。','Documents are processed locally. Sharing sends the selected copy only to invited LAN peers.')}</p></div><div class="runtime-status"><strong>{t('内置处理组件','Bundled components')}</strong>{#each Object.entries(caps) as [name,ready]}<div><span>{name}</span><small class:ready>{ready?t('就绪','Ready'):t('未安装','Missing')}</small></div>{/each}</div><label>GitHub<input type="url" bind:value={githubUrl} placeholder="https://github.com/owner/repository"/></label><p class="settings-version">BPDF 0.1.0 · AGPL-3.0</p></div></div>{/if}

{#if showCollaboration}<CollaborationDialog {lang} draft={collaborationDraft} document={active} room={active?rooms[active.id]:undefined} onclose={()=>showCollaboration=false} onjoined={joined} onleave={leaveRoom} onretry={()=>syncRooms(true)}/>{/if}

{#if showShortcuts}<div class="modal-backdrop" use:motion={{kind:'backdrop'}}><div class="compact-dialog" in:surfaceTransition={{kind:'dialog'}} out:surfaceTransition={{kind:'dialog',exit:true}} role="dialog" aria-modal="true" aria-label={t('快捷键','Keyboard shortcuts')}><div class="field-heading"><h2>{t('快捷键','Keyboard shortcuts')}</h2><button class="icon-button" onclick={()=>showShortcuts=false}><X size={18}/></button></div>{#each [
 [t('放大 / 缩小','Zoom in / out'),'+ / −'],[t('全屏','Full screen'),'L'],[t('分页栏','Page pane'),'Shift + L'],[t('打开 / 另存 / 查找','Open / Save copy / Find'),'O / S / F'],[t('打印 / 关闭文档','Print / Close document'),'P / W'],[t('适合页面 / 实际大小 / 适合宽度','Fit page / Actual size / Fit width'),'0 / 1 / 2'],[t('跳转页码','Go to page'),'Shift + N'],[t('下一个 / 上一个查找结果','Next / Previous search result'),'G / Shift + G'],[t('撤销 / 重做','Undo / Redo'),'Z / Shift + Z']
 ] as row}<p class="shortcut-row"><span>{row[0]}</span><kbd>{isMac?'⌘':'Ctrl'} + {row[1]}</kbd></p>{/each}<p class="shortcut-row"><span>{t('切换文档标签','Switch document tab')}</span><kbd>Ctrl + Tab / Shift + Tab</kbd></p><p class="shortcut-row"><span>{t('首页 / 末页','First / Last page')}</span><kbd>Home / End</kbd></p><p class="shortcut-row"><span>{t('上一屏 / 下一屏','Previous / Next screen')}</span><kbd>Page Up / Page Down · Shift + Space / Space</kbd></p><p class="shortcut-row"><span>{t('分页栏 / 退出全屏','Page pane / Exit full screen')}</span><kbd>F4 / Esc</kbd></p><p class="hint">{t('双指捏合缩放，双指平移滚动。','Pinch to zoom; two-finger pan to scroll.')}</p><p class="hint">{t('输入文字时保留常规编辑按键。Office 编辑中使用 ⌘/Ctrl + Enter 应用当前修改。','Typing keeps normal editing keys. Use ⌘/Ctrl + Enter to apply the current Office edit.')}</p></div></div>{/if}

{#if showQuit}<div class="modal-backdrop" style="z-index:1000" use:motion={{kind:'backdrop'}}><div class="compact-dialog" role="alertdialog" aria-modal="true" aria-labelledby="quit-title" tabindex="-1" use:quitFocus in:surfaceTransition={{kind:'dialog'}}><h2 id="quit-title">{t('保存修改后退出？','Save changes before quitting?')}</h2><p>{t('保存将更新原文件；另存为可选择新位置。所有文档保存成功后才会退出。','Save updates original files; Save As lets you choose new locations. Quit only after all documents save successfully.')}</p>{#if running||editing}<p class="hint">{t('当前仍有处理中的任务，请等待完成或取消任务后再退出。','Processing is still active. Wait for completion or cancel tasks before quitting.')}</p>{/if}{#if Object.keys(rooms).length}<p class="hint">{t('协作文档将另存为本地副本；退出后结束连接。','Shared documents are saved as local copies; quitting ends connections.')}</p>{/if}{#if quitError}<p class="error-message" role="alert">{quitError}</p>{/if}<div class="quit-actions"><button class="primary" disabled={quitBusy} onclick={()=>finishQuit('save')}>{t('保存并退出','Save and Quit')}</button><button class="secondary" disabled={quitBusy} onclick={()=>finishQuit('copy')}>{t('另存为并退出','Save As and Quit')}</button><button class="secondary" disabled={quitBusy} onclick={()=>finishQuit('discard')}>{t('放弃并退出','Discard and Quit')}</button><button class="secondary" disabled={quitBusy} onclick={()=>showQuit=false}>{t('取消','Cancel')}</button></div></div></div>{/if}
<style>.quit-actions{display:grid;gap:8px;margin-top:20px}.quit-actions .primary{background:#3979ed;color:#fff}</style>
